select:
SELECT 
  FROM tc_model_dcop_item
 WHERE model_version_key = #{modelVersionKey}
   AND dcop_item_name = #{dcopItemName}

SELECT 
  FROM tc_model_dcop_item
 WHERE model_version_key = #{modelVersionKey}
 ORDER BY order_rule ASC, dcop_item_name ASC

    LIMIT #{limit} OFFSET #{offset}

delete:
DELETE FROM tc_model_dcop_item
 WHERE model_version_key = #{modelVersionKey}
   AND dcop_item_name = #{dcopItemName}
